--- 设置先后手标识的显示状态
---@param state boolean 显示状态
---@param first integer 1：先手 2：后手
---@param color integer 0：蓝色（我方）1：红色（对方）
function UIBattlingPlayerHeadNode:SetFirstHandNodeState(state, first, color)
    KTool.SetActive(self.RT_HandNodeBlue.gameObject, false)
    KTool.SetActive(self.RT_HandNodeRed.gameObject, false)

    local RT_HandNode = color == 0 and self.RT_HandNodeBlue or self.RT_HandNodeRed
    KTool.SetActive(RT_HandNode.gameObject, state)
    local desc = RT_HandNode:Find("TxtHandDesc")
    local switchText = desc:GetComponent(typeof(CS.Game.Native.Common.UISwitchText))
    if not isNull(switchText) then
        switchText.Status = first
    end
end

