--- 显示表情消息
---@param emojiVoId integer
function UIBattlingPlayerHeadNode:ShowEmoji(emojiVoId)
    if IsNull(self.RT_EmojiNode) or isNull(self.LT_EmojiNode) then return end
    if self.coShowEmoji then
        cs_coroutine.stop(self.coShowEmoji)
        self.coShowEmoji = nil
    end

    local settingMgr = SettingMgr:GetInstance()
    local setting = settingMgr:GetSetting(AutoIds.IdSetting2767, "GoodsEmojiVo")
    ---@type GoodsEmojiVo
    local emojiVo = setting:Get(emojiVoId)

    self.coShowEmoji = cs_coroutine.start(function()
        cs_coroutine.yield_return(self.LT_EmojiNode:SetEmojiSkeletonGraphic(emojiVo.prefabPath))
        self.LT_EmojiNode:SetUseDynamic()
        KTool.SetActive(self.RT_EmojiNode.gameObject, true)

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(emojiVo.animationDuration / 1000))

        KTool.SetActive(self.RT_EmojiNode.gameObject, false)
        self.coShowEmoji = nil
    end)
end

--- 设置表情框的箭头位置
