---@param dir integer 0：左边 1：右边
function UIBattlingPlayerHeadNode:SetEmojiMsgRootDirection(dir)
    self.RT_EmojiNode = dir == 0 and self.RT_EmojiNodeL or self.RT_EmojiNodeR
    KTool.SetParent(self.LB_EmojiNode.gameObject, self.RT_EmojiNode.gameObject)
end

--- 设置玩家信息
---@param playerDesc table
function UIBattlingPlayerHeadNode:SetPlayerInfo(playerDesc)
    if not IsNull(self.Txt_PlayerName) then
        self.Txt_PlayerName.text = tostring(playerDesc.name)
    end
    
    self.playerId = playerDesc.playerId
    local avatarId = checkInt(playerDesc.avatar)
    local avatarFrameId = checkInt(playerDesc.avatarFrame)

    self.LT_PlayerHeadNode:FreshAvatarFrame(avatarId, avatarFrameId)
end

--- 设置点击时候的按钮回调
---@param callback function
function UIBattlingPlayerHeadNode:SetOnClickCallback(callback)
    self.LT_PlayerHeadNode:SetCallBack(callback)
end

--- 显示麦克风状态节点
---@param direction integer 0：左边 1：右边
function UIBattlingPlayerHeadNode:ShowMicStateNode(direction)
    local root = self:GetMicStateNodeRoot(direction)
    KTool.SetParent(self.RT_MicStateNode.gameObject, root.gameObject)
    KTool.SetActive(root, true)

    local lb = GetLuaBehaviour(self.RT_MicStateNode.gameObject, "Game.Behaviours.CommonMicStateNode")
    lb.Env:SetPlayerId(self.playerId)
end

function UIBattlingPlayerHeadNode:GetMicStateNodeRoot(direction)
    local root = direction == 0 and self.RT_MicRootLeft or self.RT_MicRootRight
    return root
end

return UIBattlingPlayerHeadNode